using System;using System.Collections.Generic;public class Solution{public int GetMaxGridHappiness(int m,int n,int introvertsCount,int extrovertsCount){int I=introvertsCount,E=extrovertsCount;if(n>m){int t=m;m=n;n=t;}int k=1;for(int j=0;j<n;j++)k*=3;int[]h=new int[k],a=new int[k],b=new int[k];for(int x=0;x<k;x++){int q=x,p=0;for(int j=0;j<n;j++){int d=q%3;q/=3;if(d==1){h[x]+=120;a[x]++;}else if(d==2){h[x]+=40;b[x]++;}if(d>0&&p>0)h[x]+=(d==1?-30:20)+(p==1?-30:20);p=d;}}var M=new Dictionary<string,int>();int F(int r,int i,int e,int p){if(r==m)return 0;string z=$"{r},{i},{e},{p}";if(M.TryGetValue(z,out var v))return v;v=0;for(int c=0;c<k;c++)if(a[c]<=i&&b[c]<=e){int x=p,y=c,s=0;for(int j=0;j<n;j++){int u=x%3,d=y%3;x/=3;y/=3;if(u>0&&d>0)s+=(u==1?-30:20)+(d==1?-30:20);}v=Math.Max(v,h[c]+s+F(r+1,i-a[c],e-b[c],c));}M[z]=v;return v;}return F(0,I,E,0);}}
